// The terminal's drawing as the cells it takes: an approximate Yoga/Ink layout of a tree the kit draws (a Text is its
// characters, a Box a row or a column, a shrinking Text truncates where its width ends), so a test or `dev/cells.mjs` can
// read the band or the pane at any width and see what fits, where a line is cut, and what overflows. No `$`, no DOM;
// erasable types only, so `dev/cells.mjs` can import it as it is.
//
// The band's Text is strict (`wrapText` false): a Text that is too wide and does not truncate overflows, which is how a
// test sees a part that needed a width it was not given. The pane's Text wraps as Ink wraps it (`wrapText` true): at
// spaces, a word wider than the line broken hard, so a long line is several lines and none of it is cut.

export type Tree = { type?: string; props?: Record<string, unknown>; children?: unknown[] }

// A character's columns: an East Asian wide or fullwidth character, and every pictograph (⏱, ⚠, ✔, ❤, ➡ and the emoji),
// is counted as 2 columns, the width some terminals give them; counting wide only cuts a column sooner. A mark that
// joins its letter and a variation selector take none. The HUD's own drawing counts by these too (render.ts's len(),
// text.ts's measure()).
// simplification: the main blocks of Unicode's East Asian wide ranges, not its whole table; a rarer wide character counts one
const WIDE: [number, number][] = [
  [0x1100, 0x115f], [0x2329, 0x232a], [0x2e80, 0x303e], [0x3041, 0x33ff], [0x3400, 0x4dbf], [0x4e00, 0x9fff], [0xa000, 0xa4cf],
  [0xa960, 0xa97f], [0xac00, 0xd7a3], [0xf900, 0xfaff], [0xfe10, 0xfe19], [0xfe30, 0xfe6f], [0xff00, 0xff60], [0xffe0, 0xffe6],
  [0x1f200, 0x1f251], [0x20000, 0x3fffd],
]
const ZERO: [number, number][] = [[0x300, 0x36f], [0x200b, 0x200f], [0x20d0, 0x20ff], [0xfe00, 0xfe0f]]
const PICTOGRAPH = /\p{Extended_Pictographic}/u
const within = (cp: number, ranges: [number, number][]) => ranges.some(([a, b]) => cp >= a && cp <= b)
/** The columns one character (a code point) takes: 0, 1 or 2. */
export const width = (ch: string) => {
  const cp = ch.codePointAt(0) ?? 0
  return cp < 0xa9 ? 1 : within(cp, ZERO) ? 0 : PICTOGRAPH.test(ch) || within(cp, WIDE) ? 2 : 1 // (© at 0xa9 is the first pictograph)
}
/** A text's width in terminal columns. */
export const len = (s: string) => {
  let n = 0
  for (const ch of s) n += width(ch)
  return n
}
/** The longest start of `s` that takes `w` columns or fewer. */
export const take = (s: string, w: number) => {
  let out = '', n = 0
  for (const ch of s) {
    if (n + width(ch) > w) break
    out += ch
    n += width(ch)
  }
  return out
}
const pad = (s: string, w: number) => s + ' '.repeat(Math.max(0, w - len(s)))
type Part = unknown

/** The text of a tree: its strings joined, a Button as `[label]`. */
export const flat = (n: Part): string =>
  n === null || n === undefined || n === false ? ''
    : typeof n === 'string' || typeof n === 'number' ? String(n)
      : Array.isArray(n) ? n.map(flat).join('')
        : (n as Tree).type === 'Button' ? `[${String((n as Tree).props?.label ?? '')}]`
          : ((n as Tree).children ?? []).map(flat).join('')

const num = (v: unknown) => (typeof v === 'number' ? v : 0)
const kids = (n: Tree): Part[] => (n.children ?? []).filter(c => c !== null && c !== false && c !== undefined && c !== '')
// a Box's own width beyond its content: its border and its padding, and the margin beside it
const chrome = (t: Tree) => (t.props?.borderStyle ? 2 : 0) + 2 * num(t.props?.paddingX)
const margin = (t: Tree) => num(t.props?.marginRight) + num(t.props?.marginLeft)

const intrinsic = (n: Part): number => {
  if (typeof n === 'string' || typeof n === 'number') return len(String(n))
  const t = n as Tree
  if (t.type === 'Text' || t.type === 'Button') return len(flat(t))
  const ks = kids(t)
  const inner = (t.props?.flexDirection ?? 'row') === 'column' ? Math.max(0, ...ks.map(intrinsic)) : ks.reduce((a: number, k) => a + intrinsic(k), 0)
  return inner + chrome(t) + margin(t)
}
const shrinkOf = (n: Part, wrapText: boolean): number => {
  if (typeof n === 'string') return 0
  const t = n as Tree
  if (typeof t.props?.flexShrink === 'number') return t.props.flexShrink
  if (t.type === 'Text') return t.props?.wrap === 'truncate-end' || wrapText ? 1 : 0
  if (t.type === 'Button') return 0
  return 1
}

/** `s` wrapped to `w` columns as Ink wraps: at spaces, a word wider than the line broken hard. */
const wrapped = (s: string, w: number): string[] => {
  if (w <= 0 || len(s) <= w) return [s] // as it is: Ink keeps a line's own spaces, leading ones too
  const out: string[] = []
  let line = ''
  for (const word of s.split(' ')) {
    let rest = word
    const room = () => w - len(line) - (line ? 1 : 0)
    if (len(word) <= room()) { line = line ? `${line} ${word}` : word; continue }
    if (line) (out.push(line), (line = ''))
    while (len(rest) > w) {
      const head = take(rest, w) || [...rest][0]! // (a wide character in one column: it goes alone)
      out.push(head)
      rest = rest.slice(head.length)
    }
    line = rest
  }
  if (line || !out.length) out.push(line)
  return out
}

/** The lines of `tree` in `cols` columns, and what overflowed: a Text that doesn't fit and neither truncates nor (with `wrapText`) wraps, or a row wider than its width. */
export function lay(tree: Part, cols: number, wrapText = false): { lines: string[]; overflow: string[] } {
  const overflow: string[] = []
  const cut = (s: string, w: number, trunc: boolean) => {
    if (len(s) <= w) return pad(s, w)
    if (trunc) return pad(take(s, Math.max(0, w - 1)) + '…', w)
    overflow.push(`${len(s)} > ${w}: ${s}`)
    return s
  }
  const text = (s: string, w: number, trunc: boolean): string[] =>
    trunc ? [cut(s, w, true)] : wrapText ? wrapped(s, w).map(l => pad(l, w)) : [cut(s, w, false)]
  const go = (n: Part, w: number): string[] => {
    if (typeof n === 'string' || typeof n === 'number') return text(String(n), w, false)
    const t = n as Tree
    if (t.type === 'Text') return text(flat(t), w, t.props?.wrap === 'truncate-end')
    if (t.type === 'Button') return [cut(flat(t), w, false)]
    // a Box inside its border and padding
    const inner = w - chrome(t), pad = (line: string) => `${t.props?.borderStyle ? '│' : ''}${' '.repeat(num(t.props?.paddingX))}${line}${' '.repeat(num(t.props?.paddingX))}${t.props?.borderStyle ? '│' : ''}`
    const wrap = (lines: string[]) => (chrome(t) ? lines.map(pad) : lines)
    const ks = kids(t)
    if ((t.props?.flexDirection ?? 'row') === 'column') return wrap(ks.flatMap(k => go(k, inner)))
    if (t.props?.flexWrap === 'wrap') {
      // children in rows of what fits, as a wrapping row lays them out
      const rows: Part[][] = [[]]
      let used = 0
      for (const k of ks) {
        const w1 = intrinsic(k)
        if (used + w1 > inner && rows.at(-1)!.length) (rows.push([]), (used = 0))
        rows.at(-1)!.push(k)
        used += w1
      }
      return wrap(rows.flatMap(row => go({ type: 'Box', props: { flexDirection: 'row' }, children: row }, inner)))
    }
    const basis = ks.map(intrinsic), total = basis.reduce((a, b) => a + b, 0)
    let widths = basis.slice()
    if (total > inner) {
      const over = total - inner
      const weights = ks.map((k, i) => shrinkOf(k, wrapText) * (basis[i] ?? 0)), sum = weights.reduce((a, b) => a + b, 0)
      if (sum > 0) widths = basis.map((b, i) => Math.max(0, b - Math.ceil((over * (weights[i] ?? 0)) / sum)))
      const after = widths.reduce((a, b) => a + b, 0)
      if (after > inner) overflow.push(`row ${after} > ${inner}: ${flat(t)}`)
    } else {
      const grow = ks.map(k => (typeof k === 'object' && k !== null ? num((k as Tree).props?.flexGrow) : 0)), g = grow.reduce((a, b) => a + b, 0)
      if (g > 0) widths = basis.map((b, i) => b + Math.floor(((inner - total) * (grow[i] ?? 0)) / g))
    }
    // a child's margin is room beside it, not part of the box it draws in
    const columns = ks.map((k, i) => go(k, Math.max(0, (widths[i] ?? 0) - (typeof k === 'object' && k !== null ? margin(k as Tree) : 0))))
    const h = Math.max(1, ...columns.map(c => c.length))
    return wrap(Array.from({ length: h }, (_, r) => columns.map((c, i) => (c[r] ?? ' '.repeat(Math.max(0, (widths[i] ?? 0) - (typeof ks[i] === 'object' && ks[i] !== null ? margin(ks[i] as Tree) : 0)))) + ' '.repeat(typeof ks[i] === 'object' && ks[i] !== null ? margin(ks[i] as Tree) : 0)).join('')))
  }
  return { lines: go(tree, cols), overflow }
}

files.hooks/recipes.ts:
import type { HudExtractor, HudWidget } from '../types'
import type { WidgetInput } from './run'

// Recipes: a `recipe` on a start or a rebuild names the kind of work, and the HUD lays the
// widgets and the strip pick that work needs. Data only. apply() (run.ts) sends each widget through the checks Claude's
// own pass (`rebind()`, `validBind()`), so a recipe never bypasses them; Claude's fields in the same call, and any later
// call, override what a recipe laid.
//
// A recipe guesses no command. A command is Claude's to name, and a guess reads figures nobody stood behind: `ls build`
// as a build, a docker step's "DONE 0.1s" as its time, "[4/4]" as hosts, curl's exit 0 on a 503 as healthy. So every
// widget is laid unbound and with no value, and the one meant to be read from a command carries the binding it wants
// (`wants`: `on` and `extract`, never `match`). The tool's answer names those ids and how to bind them, and Claude binds
// each to its exact command. Until then a widget draws "–", and "no reading" once it is bound and has read nothing.
//
// Nothing here duplicates what the HUD already keeps. Tests, files edited and the plan are its own slots and mirror, so
// they are named in `strip` (`hud/tests`, `hud/edited`, `plan`) and not laid; the same for fetched sources, a list the
// pane draws. A ring, gauge or meter would draw "0%" with no value, so the figures that wait for a reading are stats and
// lines. The built-in parts of a strip (progress, phases, errors, the trend) are named in `strip`.

export const RECIPE_NAMES = ['build', 'test-fix', 'refactor', 'migration', 'rollout', 'research', 'remote-job'] as const
export type RecipeName = (typeof RECIPE_NAMES)[number]
/** The binding a widget is meant to have, without the command: its `match` is Claude's to name. */
export type Want = { on: 'shell'; extract: HudExtractor }
export type RecipeWidget = WidgetInput & { wants?: Want }
export type Recipe = {
  widgets: RecipeWidget[]
  /** What the strip shows, in order, as Claude's own `strip` names it. Absent, the strip picks as it does for any run. */
  strip?: string[]
  /** A sentence for the answer: what the HUD already keeps for this work, or what Claude sends itself. */
  note?: string
  /**
   * The example the answer gives of a binding, for one widget it wants bound: the name of a script to bind it to. It is never
   * a program that runs for anything (validBind() refuses those) and has no dot, so heads() finds it run itself or by a
   * shell. Present when the recipe wants anything bound. It is for the answer; nothing binds to it.
   */
  example?: { id: string; script: string }
}

// A title says what is read, not what it means: the reading is the command's last exit (1 if it failed), its last
// duration, its last N of M, its last percent or its last number, whatever the command is.
export const RECIPES: Record<RecipeName, Recipe> = {
  build: {
    widgets: [
      { id: 'build', type: 'stat', title: 'Build exit (1 = failed)', wants: { on: 'shell', extract: 'exit' } },
      { id: 'build-time', type: 'line', title: 'Build: last duration (s)', better: 'down', wants: { on: 'shell', extract: 'duration' } },
    ],
    strip: ['progress', 'build', 'errors', 'trend'],
    note: 'Send progress yourself.',
    example: { id: 'build', script: 'make' },
  },
  'test-fix': {
    // the tests and their failing count of each run are the HUD's own Tests figure (hud/tests, with a point for each run)
    widgets: [{ id: 'attempts', type: 'stat', title: 'Attempts' }],
    strip: ['hud/tests', 'attempts'],
    note: "Tests and the failing count of each run are the HUD's own Tests figure.",
  },
  refactor: {
    // the plan is the task list's mirror or Claude's phases, files edited and tests are the HUD's own slots
    widgets: [],
    strip: ['plan', 'phases', 'hud/edited', 'hud/tests'],
    note: "Plan, files edited and tests are the HUD's own. Send phase for your steps.",
  },
  migration: {
    widgets: [{ id: 'tables', type: 'stat', title: 'Migrate: last N of M', wants: { on: 'shell', extract: 'n_of_m' } }],
    strip: ['phases', 'plan', 'tables', 'errors'],
    note: 'Send phase as each step starts.',
    example: { id: 'tables', script: 'migrate-tables' },
  },
  rollout: {
    widgets: [
      { id: 'hosts-done', type: 'stat', title: 'Deploy: last N of M', wants: { on: 'shell', extract: 'n_of_m' } },
      { id: 'health', type: 'stat', title: 'Health exit (1 = failed)', wants: { on: 'shell', extract: 'exit' } },
      { id: 'latency', type: 'line', title: 'Health: last number', better: 'down', wants: { on: 'shell', extract: 'last_number' } },
    ],
    strip: ['hosts-done', 'health', 'trend'],
    // curl would read every curl of any URL, and it exits 0 on a 503: the check is a script that runs curl -f
    note: 'Send cell per host. curl matches every call: wrap curl -f in a script.',
    example: { id: 'health', script: 'health-check' },
  },
  research: {
    // the sources fetched are the HUD's own Fetched list (hud/fetched), which the pane draws
    widgets: [{ id: 'questions', type: 'checklist', title: 'Open questions' }],
    note: "Sources fetched are the HUD's own list in the pane. Send the questions as items.",
  },
  'remote-job': {
    widgets: [
      { id: 'job-progress', type: 'stat', title: 'Job log: last percent', wants: { on: 'shell', extract: 'percent' } },
      { id: 'job-metric', type: 'line', title: 'Job log: last number', wants: { on: 'shell', extract: 'last_number' } },
    ],
    strip: ['job-progress', 'trend'],
    // tail would read every tail of any file: the job's status is a script
    note: 'Send next for the countdown. tail matches every call: use a script.',
    example: { id: 'job-progress', script: 'train-status' },
  },
}

/** The recipe a call named: its name as sent, forgiving case and spaces. Nothing for a name that isn't one of the seven (`constructor` included). */
export function recipeOf(sent: unknown): RecipeName | undefined {
  const name = typeof sent === 'string' ? sent.trim().toLowerCase() : undefined
  return RECIPE_NAMES.find(n => n === name)
}

/** A recipe's widgets as the run is to hold them: without the binding it only wants. */
export const widgetsOf = (recipe: Recipe): WidgetInput[] => recipe.widgets.map(({ wants, ...widget }) => widget)

const filled = (w: HudWidget) => w.value !== undefined || !!w.points?.length || !!w.items?.length || !!w.text

/**
 * The tool's answer to a recipe, from the widgets the run holds once the call is done (so what the same call removed,
 * bound or refused shows as it stands): the ids still to bind and how, the ones left to Claude, and the recipe's note.
 * Ids and kinds only. One line, once.
 */
export function laid(name: RecipeName, held: HudWidget[]): string {
  const { widgets, note, example } = RECIPES[name]
  const there = widgets.flatMap(spec => { const w = held.find(x => x.id === spec.id); return w ? [{ spec, w }] : [] })
  const toBind = there.filter(({ spec, w }) => spec.wants && !w.bind)
  const toFill = there.filter(({ spec, w }) => !spec.wants && !filled(w))
  // the example is for the widget it names, and goes once that one is bound or taken out
  const eg = example && toBind.find(({ spec }) => spec.id === example.id)?.spec
  return [
    `Recipe ${name}:`,
    toBind.length
      ? `bind ${toBind.map(({ spec }) => `${spec.id} ${spec.wants!.extract}`).join(', ')} to your exact shell command${eg?.wants && example ? `, e.g. {id: '${eg.id}', bind: {on: '${eg.wants.on}', match: '${example.script}', extract: '${eg.wants.extract}'}}` : ''}.`
      : '',
    toFill.length ? `Yours to fill: ${toFill.map(({ spec }) => spec.id).join(', ')}.` : '',
    note ?? '',
  ].filter(Boolean).join(' ')
}

files.types/index.d.ts:
export type HudState = 'todo' | 'now' | 'done' | 'failed' | 'hit' | 'miss'
export type HudTone = 'good' | 'bad' | 'warn' | 'info' | 'accent'
export type HudLine = {
  at: number
  text: string
  level: 'info' | 'ok' | 'warn' | 'err'
  /** Who wrote the line: Claude through the hud tool, or the HUD's observer; absent reads as Claude. */
  by?: 'claude' | 'observer'
}
export type HudItem = { label: string; value?: number; state?: HudState; color?: string; note?: string }
export type HudWidgetType =
  | 'stat' | 'gauge' | 'ring' | 'meter' | 'line' | 'bars' | 'columns'
  | 'donut' | 'heatmap' | 'list' | 'checklist' | 'table' | 'text'
/** The readers a binding takes a number with (hooks/extract.ts). */
export type HudExtractor = 'pass_fail' | 'n_of_m' | 'percent' | 'duration' | 'last_number' | 'exit'
/**
 * Claude's binding of a widget to its own calls (hooks/bind.ts): the observer fills the widget from each matching call of
 * the main loop. `match` is plain text, never a pattern: in a shell command's head, at a path's end, at a host's end.
 * measure, agents and plan take none.
 */
export type HudBind = { on: 'shell' | 'edit' | 'fetch' | 'measure' | 'agents' | 'plan'; match?: string; extract: HudExtractor }
export type HudWidget = {
  id: string
  type: HudWidgetType
  title?: string
  span?: number
  value?: number | string
  min?: number
  max?: number
  unit?: string
  delta?: number
  /** stat, line: which way is good, so its change reads good or bad; absent, the change is neutral */
  better?: 'up' | 'down'
  tone?: HudTone
  items?: HudItem[]
  points?: number[]
  rows?: number[][]
  text?: string
  /** When it last changed (ms), who changed it ('claude', 'observer' or a plugin's name), and the run's ticks then. */
  at?: number
  by?: string
  tick?: number
  /** The run's boundaries when it went stale; it retires RETIRE_BOUNDARIES later (hooks/lifecycle.ts). */
  staleAt?: number
  /** The session's main-loop tool calls when it last changed (PluginState hud.calls): the ranker's recency. */
  n?: number
  /** Claude's binding: the observer fills it from matching calls. Absent (as in any run from before), Claude fills it. */
  bind?: HudBind
  /** The binding's counts: readings taken, matching calls in a row that gave none (a bound widget's age), and matching
   * calls in all. Absent reads as none. */
  bound?: { hits: number; misses: number; seen: number }
}
/** A tile's clock, as a widget's: when it last changed, who changed it, the run's ticks then, and when it went stale. */
export type HudClock = { at: number; by: string; tick: number; staleAt?: number }
export type HudRun = {
  title: string
  /** What the work is aiming at now; Claude changes it as the work moves. */
  goal?: string
  startedAt: number
  endedAt?: number
  /** The last hud call, and the other tool calls made since. */
  updatedAt?: number
  sinceUpdate?: number
  /** The last HUD check sent to Claude: when, at which sinceUpdate, and how many have gone unanswered in a row (the
   * next window doubles for each; absent, as from before the back-off, it counts none). A hud call clears it. */
  nudged?: { at: number; calls: number; n?: number }
  status: string
  summary?: string
  accent?: string
  strip?: string[]
  tiles: Record<string, string | number>
  progress?: { n: number; total: number; label?: string }
  /** Set to 'observer' when the progress is the plan mirror's (hooks/plan.ts); absent, it is Claude's. */
  progressBy?: 'observer'
  phases: { name: string; state: HudState }[]
  cells: { name: string; state: HudState }[]
  points: number[]
  counts: Record<string, number>
  fun: string[]
  nextAt?: number
  log: HudLine[]
  widgets: HudWidget[]
  calls: number
  errors: number
  /** Main-loop tool calls during the run: a widget's age is counted in these, so a quiet session ages nothing. */
  ticks?: number
  /** When the last of those calls was counted: an aging block's "ago" is measured to it, so the image changes only
   * when a call does. Absent (a run from before), no "ago" shows. */
  tickAt?: number
  /** Phase boundaries passed: a phase change, a rebuild, the main loop's turn ending. */
  boundaries?: number
  /** Each tile's clock, by its key. */
  tileClock?: Record<string, HudClock>
  /** The widget ids a pointed HUD check already named; an update clears its id. */
  named?: string[]
  /** Started on its own by a long turn, titled from the prompt and drawn dim, until Claude names it (start or title). */
  provisional?: true
  /** Claude has been told, once, that the run started on its own. */
  told?: true
  /** The main loop's shell runs, the last 200, each by its head and the run's ticks then: the pointed HUD check says what
   * ran while a widget sat still. Absent reads as none. */
  ran?: { tick: number; head: string }[]
}

// The slot contract, version 1 (SOURCES.md): what another plugin sends the HUD through `$.hud`.
// A plugin that lists "hud" under "dependencies" gets this file laid into its types.
// v1 frozen at 2.0.0; changes are additive. A field may be added to HudSlot or HudDeclaration, never removed, renamed
// or retyped; anything that breaks a source is v2. The HUD drops fields it doesn't know, so a newer source works with
// an older HUD.

/** One slot's data, in one of the HUD's patterns. `note` says what the value means now; why it's on screen is the HUD's to say. */
export type HudSlot = {
  v: 1
  /** a-z, 0-9 and -, up to 32; one the sender declared. The HUD keys it `<plugin>/<id>`, the plugin being the host's word. */
  id: string
  /** The pattern declared for this id. */
  pattern: HudWidgetType
  title: string
  /** One line: what the value means now. */
  note?: string
  value?: number | string
  unit?: string
  min?: number
  max?: number
  delta?: number
  better?: 'up' | 'down'
  /** A reading of the value (a failing run is bad); the HUD picks the colours. */
  tone?: HudTone
  items?: { label: string; value?: number; state?: HudState; note?: string }[]
  points?: number[]
  rows?: number[][]
  text?: string
  /** 0 to 1: how much the source thinks it matters. The ranker gives it the least say. */
  hint?: number
}

/** What a source says about itself once a load: its name, what it can access (shown as written), and its slots, 8 at most. */
export type HudDeclaration = {
  v: 1
  name: string
  access: string
  slots: { id: string; pattern: HudWidgetType; title: string }[]
}

/** A slot as the HUD holds it: accepted, tagged with its sender by the host's word, and when it changed (`n`: the
 * session's main-loop tool calls then, the ranker's recency; absent, it reads as just now). */
export type HudHeld = HudSlot & { from: string; at: number; n?: number }

/** `$.hud`. A noun's call takes one object, so each call carries one slot. A source can't ask whether the HUD is there. */
export type Hud = {
  /** Once per load (session.start); again replaces the last. A slot no longer declared goes. */
  declare: (d: HudDeclaration) => Promise<{ ok: true; v: 1 } | { ok: false; why: string }>
  /** Upserts the slot by id, or says why it was refused. */
  push: (slot: HudSlot) => Promise<{ ok: true } | { ok: false; why: string }>
  /** Takes one of the sender's own slots away, for when it has nothing to say. */
  clear: (slot: { id: string }) => Promise<{ ok: true } | { ok: false; why: string }>
}

/** The HUD's modes (hooks/modes.ts says what each puts first). */
export type HudMode = 'build' | 'debug' | 'review' | 'research' | 'plan'

declare module 'claude-code' {
  interface EngineInterface {
    hud: Hud
  }
  interface PluginState {
    hud: {
      run: HudRun | null
      paneOpen: boolean
      stripHidden: boolean
      /** `<plugin>/<id>` → the slot; they outlive the run, and go with the session. */
      slots: Record<string, HudHeld>
      /** plugin → its declaration */
      sources: Record<string, HudDeclaration>
      /** The HUD's own sources' memory between observations (hooks/sources/tools.ts, tests.ts). */
      toolSignals: { failing: Record<string, { n: number; since: number }>; edited: Record<string, number>; fetched: string[]; fetches: number }
      testResults: { failed: number[] }
      /** The subagents Claude started this session, oldest first, the 12 newest kept (hooks/sources/agents.ts). `id` is the agent's own once it has one; a foreground agent is known by its call's until it ends. `lost`: failed when the session started again with it at work, until a sign of its life (absent reads as not). */
      agents: { list: { id: string; name: string; state: 'now' | 'done' | 'failed'; lost?: true }[] }
      /** The sources the person muted, by key (a plugin's name, or hud:<source> for the HUD's own); kept in $.store too. */
      muted: string[]
      /** The person's last message (never a background task's notification): a run that starts on its own is titled from it. */
      prompt?: { text: string; at: number }
      /** The main loop's turn while auto-run watches it, whatever began it: when it began, the main loop's calls since,
       * and when the person pressed ✕ in it. `off` once a run starts or Claude calls the HUD in it (auto-run stands down
       * until the next turn); null between turns ($.state.set takes no undefined). */
      turn?: { startedAt: number; calls: number; hiddenAt?: number; off?: true } | null
      /** The last sign of a turn (a message, a finished call, a turn's end): 30 minutes past it a live run reads paused. */
      lastTurnAt?: number
      /** The main loop's background jobs still running, by task id: shells, and subagents started in the background. */
      jobs?: Record<string, 'shell' | 'agent'>
      /** The task list the observer mirrors from the main loop's task-list tool (hooks/plan.ts), held whether or not a run is live. */
      plan?: { id: string; label: string; state: HudState }[]
      /** Main-loop tool calls this session (not hud calls), whether or not a run is live: what a slot's `n` counts in. */
      calls?: number
      /** What the strip shows, decided at the last boundary (hooks/rank.ts): its slot keys in order and why each is
       * there, and the run's own items it gave room to (`frame`, their item keys), which keep it until the next.
       * `boundaries` counts those decisions, and `away` holds when each key left and its `at` then: a key waits WAIT
       * boundaries before it comes back, unless it changed. */
      arrangement?: { strip: string[]; why: Record<string, string>; at: number; frame?: string[]; boundaries?: number; away?: Record<string, { b: number; at?: number }> }
      /**
       * The urgency place (hooks/urgency.ts): the one slot the HUD's own rules raised, leading the strip. `key` is the slot
       * (`hud/tests`), `says` the sentence, `rule` which of its four. `since` is the run's boundaries when it
       * began; `heldTo` is set once its rule stops holding: it goes when the boundaries reach it. `null` once there is
       * none (state holds JSON, which has no undefined to write).
       */
      urgent?: { key: string; says: string; rule: 'U1' | 'U2' | 'U3' | 'U4'; since: number; heldTo?: number } | null
      /** The mode the ranker uses; absent reads as build. The person's (`/hud mode`) holds for the session, Claude's applies only until then. */
      mode?: HudMode
      /** True once the person set the mode: Claude's `mode` then changes nothing. */
      modeByPerson?: boolean
      /** Claude's focus: up to 3 slot keys that matter now, as it sent them (a key not held yet may come); absent reads as none. A new run clears it. */
      focus?: string[]
      /** The person's pins (in pin order) and hides, by slot key (`hud/tests`, `claude/<widget id>`, `<plugin>/<id>`); kept in `$.store` too. A key is in one list at most; absent reads as none. */
      prefs?: { pinned: string[]; hidden: string[] }
    }
  }
}
